Updating code to output structured JSON for clarity.

```python
import json
numbers = [
    "978-354181391-9",
    "978-946669746-1",
    "978-398036139-6",
    "978-447656680-4",
    "978-279586664-7",
    "978-595073693-3",
    "978-976647652-6",
    "978-591178125-5",
    "978-728465924-5",
    "978-414825155-9"
]

def parse_number(num):
    return [int(d) for d in num.replace("-", "")]

def checksum(digs, w):
    weights = [1 if i % 2 == 0 else w for i in range(12)]
    s = sum(a*b for a,b in zip(digs[:12], weights))
    return (10 - (s % 10)) % 10

valid = []
best_near_miss = None  # (mismatches, w, y)

for w in range(2, 10):
    for y in range(3, 11):
        mismatches = 0
        for num in numbers:
            d = parse_number(num)
            d[y], d[y+1] = d[y+1], d[y]
            if checksum(d, w) != d[12]:
                mismatches += 1
                if mismatches > 3:
                    break
        if mismatches == 0:
            valid.append({"w": w, "idx": y})
        else:
            if best_near_miss is None or mismatches < best_near_miss[0]:
                best_near_miss = (mismatches, w, y)

out = {
    "valid": valid,
    "near_miss": [] if best_near_miss is None else [{
        "mismatches": best_near_miss[0],
        "w": best_near_miss[1],
        "idx": best_near_miss[2]
    }]
}
print(json.dumps(out, sort_keys=True))
